-- Forward-only correction. 0066 is reserved for independent import admissions.
-- Preserve every causal bump for changed machine reach, without multiplying all-account bumps by selector count.
-- Selection rows only change their own entry; profile/token changes affect current/old/new scoped reach.
DROP TRIGGER audience_machine_profiles_insert;
CREATE TRIGGER audience_machine_profiles_insert AFTER INSERT ON machine_profiles BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE ((entries.owner_id=NEW.creator_id OR EXISTS (SELECT 1 FROM entry_readers r WHERE r.entry_id=entries.entry_id AND r.recipient_id=NEW.creator_id AND r.allow_automation=1)) AND (NEW.mode='all' OR (NEW.mode='allow' AND EXISTS (SELECT 1 FROM machine_profile_entries n WHERE n.profile_id=NEW.profile_id AND n.entry_id=entries.entry_id)) OR (NEW.mode='deny' AND NOT EXISTS (SELECT 1 FROM machine_profile_entries n WHERE n.profile_id=NEW.profile_id AND n.entry_id=entries.entry_id)))); END;
DROP TRIGGER audience_machine_profiles_update;
CREATE TRIGGER audience_machine_profiles_update AFTER UPDATE ON machine_profiles BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE ((entries.owner_id=OLD.creator_id OR EXISTS (SELECT 1 FROM entry_readers r WHERE r.entry_id=entries.entry_id AND r.recipient_id=OLD.creator_id AND r.allow_automation=1)) AND (OLD.mode='all' OR (OLD.mode='allow' AND EXISTS (SELECT 1 FROM machine_profile_entries n WHERE n.profile_id=OLD.profile_id AND n.entry_id=entries.entry_id)) OR (OLD.mode='deny' AND NOT EXISTS (SELECT 1 FROM machine_profile_entries n WHERE n.profile_id=OLD.profile_id AND n.entry_id=entries.entry_id)))) OR ((entries.owner_id=NEW.creator_id OR EXISTS (SELECT 1 FROM entry_readers r WHERE r.entry_id=entries.entry_id AND r.recipient_id=NEW.creator_id AND r.allow_automation=1)) AND (NEW.mode='all' OR (NEW.mode='allow' AND EXISTS (SELECT 1 FROM machine_profile_entries n WHERE n.profile_id=NEW.profile_id AND n.entry_id=entries.entry_id)) OR (NEW.mode='deny' AND NOT EXISTS (SELECT 1 FROM machine_profile_entries n WHERE n.profile_id=NEW.profile_id AND n.entry_id=entries.entry_id)))); END;
DROP TRIGGER audience_machine_profiles_delete;
CREATE TRIGGER audience_machine_profiles_delete AFTER DELETE ON machine_profiles BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE ((entries.owner_id=OLD.creator_id OR EXISTS (SELECT 1 FROM entry_readers r WHERE r.entry_id=entries.entry_id AND r.recipient_id=OLD.creator_id AND r.allow_automation=1)) AND (OLD.mode='all' OR (OLD.mode='allow' AND EXISTS (SELECT 1 FROM machine_profile_entries n WHERE n.profile_id=OLD.profile_id AND n.entry_id=entries.entry_id)) OR (OLD.mode='deny' AND NOT EXISTS (SELECT 1 FROM machine_profile_entries n WHERE n.profile_id=OLD.profile_id AND n.entry_id=entries.entry_id)))); END;
DROP TRIGGER audience_machine_profile_entries_insert;
CREATE TRIGGER audience_machine_profile_entries_insert AFTER INSERT ON machine_profile_entries BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE entries.entry_id=NEW.entry_id; END;
DROP TRIGGER audience_machine_profile_entries_update;
CREATE TRIGGER audience_machine_profile_entries_update AFTER UPDATE ON machine_profile_entries BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE entries.entry_id=OLD.entry_id OR entries.entry_id=NEW.entry_id; END;
DROP TRIGGER audience_machine_profile_entries_delete;
CREATE TRIGGER audience_machine_profile_entries_delete AFTER DELETE ON machine_profile_entries BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE entries.entry_id=OLD.entry_id; END;
DROP TRIGGER audience_machine_tokens_insert;
CREATE TRIGGER audience_machine_tokens_insert AFTER INSERT ON machine_tokens BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE (EXISTS (SELECT 1 FROM machine_profiles p WHERE p.profile_id=NEW.profile_id AND (entries.owner_id=p.creator_id OR EXISTS (SELECT 1 FROM entry_readers r WHERE r.entry_id=entries.entry_id AND r.recipient_id=p.creator_id AND r.allow_automation=1)) AND (p.mode='all' OR (p.mode='allow' AND EXISTS (SELECT 1 FROM machine_profile_entries n WHERE n.profile_id=p.profile_id AND n.entry_id=entries.entry_id)) OR (p.mode='deny' AND NOT EXISTS (SELECT 1 FROM machine_profile_entries n WHERE n.profile_id=p.profile_id AND n.entry_id=entries.entry_id))))); END;
DROP TRIGGER audience_machine_tokens_update;
CREATE TRIGGER audience_machine_tokens_update AFTER UPDATE ON machine_tokens BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE (EXISTS (SELECT 1 FROM machine_profiles p WHERE p.profile_id=OLD.profile_id AND (entries.owner_id=p.creator_id OR EXISTS (SELECT 1 FROM entry_readers r WHERE r.entry_id=entries.entry_id AND r.recipient_id=p.creator_id AND r.allow_automation=1)) AND (p.mode='all' OR (p.mode='allow' AND EXISTS (SELECT 1 FROM machine_profile_entries n WHERE n.profile_id=p.profile_id AND n.entry_id=entries.entry_id)) OR (p.mode='deny' AND NOT EXISTS (SELECT 1 FROM machine_profile_entries n WHERE n.profile_id=p.profile_id AND n.entry_id=entries.entry_id))))) OR (EXISTS (SELECT 1 FROM machine_profiles p WHERE p.profile_id=NEW.profile_id AND (entries.owner_id=p.creator_id OR EXISTS (SELECT 1 FROM entry_readers r WHERE r.entry_id=entries.entry_id AND r.recipient_id=p.creator_id AND r.allow_automation=1)) AND (p.mode='all' OR (p.mode='allow' AND EXISTS (SELECT 1 FROM machine_profile_entries n WHERE n.profile_id=p.profile_id AND n.entry_id=entries.entry_id)) OR (p.mode='deny' AND NOT EXISTS (SELECT 1 FROM machine_profile_entries n WHERE n.profile_id=p.profile_id AND n.entry_id=entries.entry_id))))); END;
DROP TRIGGER audience_machine_tokens_delete;
CREATE TRIGGER audience_machine_tokens_delete AFTER DELETE ON machine_tokens BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE (EXISTS (SELECT 1 FROM machine_profiles p WHERE p.profile_id=OLD.profile_id AND (entries.owner_id=p.creator_id OR EXISTS (SELECT 1 FROM entry_readers r WHERE r.entry_id=entries.entry_id AND r.recipient_id=p.creator_id AND r.allow_automation=1)) AND (p.mode='all' OR (p.mode='allow' AND EXISTS (SELECT 1 FROM machine_profile_entries n WHERE n.profile_id=p.profile_id AND n.entry_id=entries.entry_id)) OR (p.mode='deny' AND NOT EXISTS (SELECT 1 FROM machine_profile_entries n WHERE n.profile_id=p.profile_id AND n.entry_id=entries.entry_id))))); END;
